import{_ as o}from"./chunks/architecture-zh-CN.EQpNaQPQ.js";import{_ as r,o as a,c as t,a2 as c}from"./chunks/framework.BWuWLRhz.js";const S=JSON.parse('{"title":"系統架構設計","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/dev-guide/architecture.md","filePath":"zh-TW/dev-guide/architecture.md","lastUpdated":1787586465000}'),i={name:"zh-TW/dev-guide/architecture.md"};function d(l,e,s,n,h,p){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="系統架構設計" tabindex="-1">系統架構設計 <a class="header-anchor" href="#系統架構設計" aria-label="Permalink to &quot;系統架構設計&quot;">​</a></h1><p>Lertaro 採用先進的多處理程序隔離架構與模組化分層設計，確保在實現系統級毫秒檢索與全方位視窗整合的同時，兼顧最高級別的執行安全與穩定性。</p><p><img src="'+o+'" alt="Lertaro 架構圖"></p><h2 id="_1-三處理程序隔離模型" tabindex="-1">1. 三處理程序隔離模型 <a class="header-anchor" href="#_1-三處理程序隔離模型" aria-label="Permalink to &quot;1. 三處理程序隔離模型&quot;">​</a></h2><p>為了徹底規避單一元件異常導致整個系統當機，並將 Windows 特權限制在最小範圍內，Lertaro 的執行階段被明確劃分為三個獨立的處理程序：</p><h3 id="_1-背景索引服務-lertaro-service" tabindex="-1">1. 背景索引服務（<code>Lertaro.Service</code>） <a class="header-anchor" href="#_1-背景索引服務-lertaro-service" aria-label="Permalink to &quot;1. 背景索引服務（`Lertaro.Service`）&quot;">​</a></h3><ul><li><strong>執行身分</strong>：以 Windows 系統級 <code>LocalSystem</code> 身分常駐執行的 Windows 服務。</li><li><strong>職責範圍</strong>：承擔全盤檔案索引與增量監聽的核心重任。直接讀取 NTFS / ReFS 磁碟底層的 USN 變更記錄檔與 $MFT 主檔案表；即時監聽 FAT32 / exFAT 磁碟變更；定時抓取並快取 SMB / NAS 網路共用。</li><li><strong>安全與效能考量</strong>：執行在 SYSTEM 級別使服務無需快顯任何 UAC 提權快顯視窗即可直接讀取原始磁碟卷的中繼資料；同時透過高效能具名管道向使用者態 App 返回檢索結果，徹底避免了讓前景 UI 處理程序持有不必要的全域高權限。</li></ul><h3 id="_2-使用者互動主程式-lertaro-app" tabindex="-1">2. 使用者互動主程式（<code>Lertaro.App</code>） <a class="header-anchor" href="#_2-使用者互動主程式-lertaro-app" aria-label="Permalink to &quot;2. 使用者互動主程式（`Lertaro.App`）&quot;">​</a></h3><ul><li><strong>執行身分</strong>：標準 Windows 使用者態、Session 隔離的 WPF 前景桌面應用程式。</li><li><strong>職責範圍</strong>：承載快速搜尋置中浮動視窗、完整主搜尋視窗、設定中心、全域快速鍵分發、動作功能表（<code>Ctrl+O</code>）以及 QuickLook 檔案即時預覽介面。</li><li><strong>IPC 橋樑與 CLI 裝載</strong>：透過雙向具名管道（<code>Core.Services.SearchService</code>）向背景 Service 發送搜尋請求與目錄管理指令；同時，App 自身還裝載了一條面向目前使用者的專屬具名管道服務（<code>AppSearchPipeService</code>），使外部伴隨工具（如 <code>lff</code> 命令列工具）能直接複用 App 已經建置好的記憶體別名表、外掛模組提供者與網路磁碟快取，無需重複初始化。</li></ul><h3 id="_3-全域鍵盤攔截與視窗適配處理程序-lertaro-service-hook" tabindex="-1">3. 全域鍵盤攔截與視窗適配處理程序（<code>Lertaro.Service --hook</code>） <a class="header-anchor" href="#_3-全域鍵盤攔截與視窗適配處理程序-lertaro-service-hook" aria-label="Permalink to &quot;3. 全域鍵盤攔截與視窗適配處理程序（`Lertaro.Service --hook`）&quot;">​</a></h3><ul><li><strong>執行身分</strong>：由背景服務按需拉起的獨立特權輔助處理程序。</li><li><strong>職責範圍</strong>：裝載低階全域鍵盤攔截（Low-Level Keyboard Hook）與滑鼠全域監聽。</li><li><strong>UIPI 權限突破與當機隔離</strong>：在 Windows 安全體系中，低完整性級別的使用者態處理程序無法向以管理員身分執行的最高權限視窗發送視窗訊息或模擬輸入（UIPI 隔離）。透過在該特權 Hook 處理程序中執行視窗整合適配器（<a href="./sdk/system-adapters.html"><code>IActivePathCollector</code>、<code>IFileDialogAdapter</code>、<code>IInlineSearchAdapter</code></a>），Lertaro 能夠毫無阻礙地識別並嵌入由管理員身分啟動的檔案總管、Total Commander 或第三方對話方塊。同時，即使底層攔截因第三方遊戲的反作弊模組產生異常，也不會影響主 App 處理程序的正常執行。</li></ul><h2 id="_2-共用核心層-shared-core-library" tabindex="-1">2. 共用核心層（Shared Core Library） <a class="header-anchor" href="#_2-共用核心層-shared-core-library" aria-label="Permalink to &quot;2. 共用核心層（Shared Core Library）&quot;">​</a></h2><p><code>Lertaro.Core</code> 是被 Service、App 和 Hook 處理程序同時引用的基礎類別庫，主要包含以下關鍵模組：</p><ul><li><strong>自研 fzf 模糊比對引擎（<code>Core/SearchIndex/Fzf/*</code>）</strong>：高效復刻並最佳化了知名 <code>fzf</code> 演算法的跳躍字元模糊比對、子字串分段與字元級反白計算，配合 <code>SearchQueryParser</code> 實現磁碟機定向與路徑模式切分。</li><li><strong>欄式記憶體索引（<code>Core/IndexV2/*</code>）</strong>：採用記憶體對應欄式快照（Columnar Snapshot）與記憶體增量覆蓋層（Delta Overlay），實現億級檔案項目的亞毫秒級檢索。</li><li><strong>二進位 IPC 通訊契約</strong>：定義了 <code>SearchRequestMessage</code>、<code>SearchResponseBinarySerializer</code> 等標準二進位資料通訊協定，確保多處理程序間零拷貝高效序列化。</li><li><strong>統一多處理程序記錄系統（<code>Logger</code>）</strong>：分別輸出至 <code>service.log</code>、<code>app.log</code> 與 <code>hook.log</code>，並由 App 的設定中心記錄檢視器統一代理讀取與呈現。</li></ul><h2 id="_3-外掛模組系統在架構中的定位" tabindex="-1">3. 外掛模組系統在架構中的定位 <a class="header-anchor" href="#_3-外掛模組系統在架構中的定位" aria-label="Permalink to &quot;3. 外掛模組系統在架構中的定位&quot;">​</a></h2><p>所有第三方及內建外掛模組均基於 <code>Lertaro.PluginSdk</code> 建置，由 <code>Lertaro.App</code> 處理程序在啟動時自動反映掃描並載入：</p><ul><li><strong>零特權直接通訊</strong>：外掛模組通常只與 App 處理程序進行互動，不直接與底層 Service 通訊。若外掛模組需要註冊自訂實體目錄進行長效索引，可透過 SDK 提供的 <code>DirectoryIndexerService</code> 向宿主發起代理請求。</li><li><strong>雙重載入機制</strong>：常規的搜尋來源、動作與介面擴充僅在 App 處理程序中執行；而實作了系統與視窗適配介面（<code>IActivePathCollector</code> 等）的元件會被宿主額外載入一份至 Hook 處理程序中執行，以確保跨權限視窗自動化的穩定性。</li></ul>',17)])])}const _=r(i,[["render",d]]);export{S as __pageData,_ as default};
